  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 The Home and Prepositions of Location$j$, $j${"readings": [{"title": "Proverbs 24 (King James Version)", "url": "/portal/bible/Proverbs/24"}], "body": "Proverbs 24:3 says, Through wisdom is an house builded; and by understanding it is established. A home is a place of rest, family and hospitality, and describing your home in Spanish is a practical skill.\n\nRooms in a house include la casa for house, la sala for living room, la cocina for kitchen, el comedor for dining room, el dormitorio or la habitación for bedroom, el baño for bathroom, el garaje for garage, el jardín for garden or yard and el patio for patio. Furniture and objects include la cama for bed, el sofá for sofa, la mesa for table, la silla for chair, el escritorio for desk, la lámpara for lamp, el televisor for television and la ventana for window. Many families have a place for a Bible or a picture of the family.\n\nTo say where something is, use estar with a preposition of location. These include en for in or on, sobre or encima de for on top of, debajo de for under, detrás de for behind, delante de for in front of, al lado de for next to, entre for between, cerca de for near and lejos de for far from. El libro está sobre la mesa. El gato está debajo de la silla. La cocina está al lado del comedor.\n\nUse hay to say that something exists and estar to say where a known thing is. Hay una cama en el dormitorio, but La cama está en el dormitorio. Describe your home with adjectives such as grande, pequeña, cómoda, limpia and bonita. Compare Mi casa es pequeña pero cómoda.\n\nYour task: (1) Name eight rooms or objects. (2) Write five sentences telling where things are in your home. (3) Describe your home in four sentences.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Proverbs 24:3 says, Through wisdom is an house builded; and by understanding it is established.\n\nNow watch this. La sala, la cocina, el comedor, el dormitorio, el baño, el garaje, el jardín. La cama, el sofá, la mesa, la silla, el escritorio, la ventana.\n\nTo say where something is, use estar with a preposition. En, sobre, debajo de, detrás de, delante de, al lado de, entre, cerca de, lejos de. El libro está sobre la mesa. El gato está debajo de la silla.\n\nUse hay for existence and estar for the location of a known thing. Hay una cama en el dormitorio. La cama está en el dormitorio.\n\nYour task is to name rooms and objects and write sentences about your home. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 The Home and Prepositions of Location$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 The Body, Health and the Verb Doler$j$, $j${"readings": [{"title": "Proverbs 17 (King James Version)", "url": "/portal/bible/Proverbs/17"}], "body": "Proverbs 17:22 says, A merry heart doeth good like a medicine: but a broken spirit drieth the bones. Knowing the words for the body and for how you feel lets you ask for help and care for others who speak Spanish. These lessons teach vocabulary and are not medical advice. If you or someone you care for is sick or hurt, tell a parent, guardian or doctor, or call 911 in an emergency.\n\nParts of the body include la cabeza for head, el pelo for hair, la cara for face, los ojos for eyes, la nariz for nose, la boca for mouth, los oídos for ears, el cuello for neck, el brazo for arm, la mano for hand, el dedo for finger, el pecho for chest, la espalda for back, el estómago for stomach, la pierna for leg, la rodilla for knee and el pie for foot.\n\nTo say that something hurts, use the verb doler, which works like gustar and changes o to ue. Me duele la cabeza means my head hurts. Me duelen los pies means my feet hurt. Use duele for one thing and duelen for more than one. To ask, say ¿Qué te duele? or ¿Dónde le duele? You can also say Tengo dolor de cabeza or Tengo dolor de estómago.\n\nOther health words are Estoy enfermo or enferma for I am sick, Tengo fiebre for I have a fever, Tengo tos for I have a cough, Tengo gripe for I have the flu, Estoy cansado or cansada for I am tired, el médico or la médica for doctor, la enfermera for nurse, la medicina for medicine and la cita for appointment. Say Necesito ayuda, which means I need help, and Llama al médico, which means call the doctor.\n\nYour task: (1) Name ten body parts. (2) Write four sentences using me duele or me duelen. (3) Write a short dialogue with a doctor.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Proverbs 17:22 says, A merry heart doeth good like a medicine. A quick reminder: these lessons teach vocabulary and are not medical advice. If you are sick or hurt, tell a parent or guardian or doctor, and call 911 in an emergency.\n\nNow watch this. La cabeza, los ojos, la nariz, la boca, el brazo, la mano, la pierna, el pie, el estómago, la espalda.\n\nTo say something hurts, use doler. Me duele la cabeza. Me duelen los pies. Duele is one thing. Duelen is more than one. Tengo fiebre. Tengo tos. Estoy cansado. Necesito ayuda.\n\nYour task is to name ten body parts, write four sentences with doler and write a short doctor dialogue. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 The Body, Health and the Verb Doler$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Weather, Seasons and Hobbies$j$, $j${"readings": [{"title": "Psalm 19 (King James Version)", "url": "/portal/bible/Psalms/19"}], "body": "Psalm 19:1 says, The heavens declare the glory of God; and the firmament sheweth his handywork. Weather, seasons and the things we enjoy doing are part of everyday conversation in any language.\n\nTo describe the weather, Spanish uses hacer and other verbs. ¿Qué tiempo hace? asks what is the weather. Hace calor means it is hot. Hace frío means it is cold. Hace sol means it is sunny. Hace viento means it is windy. Hace buen tiempo and hace mal tiempo mean it is good or bad weather. Llueve means it is raining, from the verb llover. Nieva means it is snowing. Está nublado means it is cloudy. Hay tormenta means there is a storm. In Florida we know the words huracán for hurricane and tormenta tropical for tropical storm. In hurricane season, listen to local officials and prepare with your family.\n\nThe seasons are la primavera for spring, el verano for summer, el otoño for autumn and el invierno for winter. Florida has a hot rainy summer and a mild dry winter. En el verano hace mucho calor y llueve por la tarde.\n\nHobbies and activities include jugar al fútbol, jugar al baloncesto, nadar, correr, leer, cantar, tocar la guitarra, tocar el piano, bailar, dibujar, escuchar música and ir a la playa. The verb jugar, which means to play a sport or game, changes u to ue: juego, juegas, juega, jugamos, juegan. Tocar is used for musical instruments. Say ¿Qué te gusta hacer? and answer Me gusta nadar and Juego al fútbol los sábados.\n\nYour task: (1) Describe the weather for each season where you live. (2) Write five sentences about your hobbies using jugar, tocar and gustar.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Psalm 19:1 says, The heavens declare the glory of God; and the firmament sheweth his handywork.\n\nNow watch this. ¿Qué tiempo hace? Hace calor. Hace frío. Hace sol. Hace viento. Llueve. Nieva. Está nublado. In Florida we know huracán and tormenta tropical. In hurricane season, listen to local officials and prepare with your family.\n\nThe seasons are la primavera, el verano, el otoño and el invierno.\n\nJugar changes u to ue. Juego, juegas, juega, jugamos, juegan. Juego al fútbol los sábados. Tocar is for instruments. Toco el piano. Me gusta nadar. Me gusta cantar en la iglesia.\n\nYour task is to describe the weather and write five sentences about your hobbies. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Weather, Seasons and Hobbies$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 The Spanish Speaking World and Hispanic Florida$j$, $j${"readings": [{"title": "Revelation 7 (King James Version)", "url": "/portal/bible/Revelation/7"}], "body": "Revelation 7:9 describes a great multitude, which no man could number, of all nations, and kindreds, and people, and tongues, standing before the throne. Learning about Spanish speaking cultures prepares us to love and serve people from many nations.\n\nSpanish is an official language in about twenty countries. In North America it is spoken in México. In Central America it is spoken in Guatemala, Honduras, El Salvador, Nicaragua, Costa Rica and Panamá. In the Caribbean it is spoken in Cuba, la República Dominicana and Puerto Rico, which is part of the United States. In South America it is spoken in Colombia, Venezuela, Ecuador, Perú, Bolivia, Chile, Argentina, Uruguay and Paraguay. In Europe it is spoken in España, and in Africa in Guinea Ecuatorial. There are also tens of millions of Spanish speakers in the United States.\n\nSpanish differs by region. In Latin America ustedes is used for you all, while in Spain vosotros is used with friends. In some places, such as Argentina, people use vos instead of tú. Words for foods and objects differ, but Spanish speakers understand each other. Respect for elders, family and hospitality are common values.\n\nFlorida has a deep Hispanic history. In 1565 Spain founded St. Augustine, the oldest continuously occupied European settlement in the continental United States. Today large Hispanic communities in Miami, Hialeah, Orlando, Tampa and Broward County include people from Cuba, Puerto Rico, Colombia, Venezuela, Nicaragua, the Dominican Republic and many other places. National Hispanic Heritage Month is celebrated from September 15 to October 15 each year.\n\nYour task: (1) Name five Spanish speaking countries and their capitals if you can find them. (2) Write four Spanish sentences about a country or culture you would like to learn about. (3) Explain how Revelation 7:9 should shape our attitude toward other cultures.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Revelation 7:9 describes a great multitude of all nations, and kindreds, and people, and tongues. Learning about other cultures prepares us to love and serve people from many nations.\n\nNow watch this. Spanish is an official language in about twenty countries. México. Guatemala, Honduras, El Salvador, Nicaragua, Costa Rica, Panamá. Cuba, la República Dominicana, Puerto Rico. Colombia, Venezuela, Ecuador, Perú, Bolivia, Chile, Argentina, Uruguay, Paraguay. España and Guinea Ecuatorial.\n\nSpanish differs by region. Latin America uses ustedes. Spain uses vosotros with friends. Some places use vos. Speakers understand each other.\n\nFlorida has a deep Hispanic history. In 1565 Spain founded St. Augustine. Today large communities in Miami, Hialeah, Orlando and Broward include people from Cuba, Puerto Rico, Colombia, Venezuela and many other places. Hispanic Heritage Month is September 15 to October 15.\n\nYour task is to name countries, write four sentences and explain Revelation 7:9. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 The Spanish Speaking World and Hispanic Florida$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Home, Health, Weather and the Spanish Speaking World$j$, $j${"prompt": "Write a report of at least 250 words in English with Spanish examples. Use complete sentences and label each part. Revelation 7:9 describes a great multitude of all nations, and kindreds, and people, and tongues.\n\nPart 1: Describe your home in Spanish in at least six sentences, using rooms, furniture, adjectives and prepositions of location.\nPart 2: Name twelve parts of the body in Spanish. Explain how doler works and write five sentences using me duele or me duelen. Note that these are vocabulary lessons and not medical advice.\nPart 3: Describe the weather in each of the four seasons where you live in Spanish and write five sentences about your hobbies using jugar, tocar and gustar.\nPart 4: Write a paragraph in English with Spanish names about three Spanish speaking countries, including one fact about each, and explain the history of Hispanic Florida.\nPart 5: Explain how Revelation 7:9, Proverbs 24:3 and Proverbs 17:22 guide you in loving people of other cultures and caring for your home and health.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 25 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Home, Health, Weather and the Spanish Speaking World$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Of All Nations, and Kindreds, and People, and Tongues$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a Spanish speaking culture or country that you would like to know better and what you would like to learn about its food, music or traditions, (2) uses at least five Spanish words or phrases from this unit, (3) explains how the church can welcome neighbors from many cultures and languages, and (4) connects your answer to Revelation 7:9, Psalm 19:1 or Proverbs 24:3. Then write a respectful reply of at least 40 words to another student's post, or answer this question: What can we learn from people whose culture is different from our own? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Of All Nations, and Kindreds, and People, and Tongues$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: The Home and Prepositions of Location$j$, $j${"questions": [{"q": "La cocina is:", "options": ["The bedroom", "The living room", "The kitchen", "The garden"]}, {"q": "Debajo de means:", "options": ["Under", "Next to", "Behind", "On top of"]}, {"q": "El libro ___ sobre la mesa.", "options": ["tiene", "hay", "está", "es"]}, {"q": "The word for bedroom is:", "options": ["Dormitorio", "Garaje", "Comedor", "Baño"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Home and Prepositions of Location$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,0}'::int[], array[$j$Cocina is kitchen.$j$,$j$Debajo de is under.$j$,$j$The location of a known thing uses estar.$j$,$j$Dormitorio means bedroom.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Home and Prepositions of Location$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: The Body, Health and the Verb Doler$j$, $j${"questions": [{"q": "Los ojos are:", "options": ["The eyes", "The hands", "The ears", "The feet"]}, {"q": "Me duelen los pies means:", "options": ["My feet hurt", "I like my feet", "My feet are big", "I have two feet"]}, {"q": "Tengo fiebre means:", "options": ["I have a cold shirt", "I have a cough", "I have a fever", "I am happy"]}, {"q": "Who should you tell first if you feel sick at home?", "options": ["Only a website", "Only a friend", "A parent, guardian or doctor", "No one"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The Body, Health and the Verb Doler$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,2}'::int[], array[$j$Ojos means eyes.$j$,$j$Duelen is plural.$j$,$j$Fiebre is fever.$j$,$j$Always seek real help from a trusted adult or doctor.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The Body, Health and the Verb Doler$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Weather, Seasons and Hobbies$j$, $j${"questions": [{"q": "Hace calor means:", "options": ["It is raining", "It is cloudy", "It is cold", "It is hot"]}, {"q": "El invierno is:", "options": ["Winter", "Spring", "Summer", "Autumn"]}, {"q": "The yo form of jugar is:", "options": ["Jugamos", "Juega", "Juego", "Jugo"]}, {"q": "We use tocar for:", "options": ["Running", "Playing an instrument", "Eating", "Playing a sport"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Weather, Seasons and Hobbies$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,2,1}'::int[], array[$j$Calor means heat.$j$,$j$Invierno is winter.$j$,$j$Jugar changes u to ue.$j$,$j$Tocar la guitarra means to play guitar.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Weather, Seasons and Hobbies$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: The Spanish Speaking World and Hispanic Florida$j$, $j${"questions": [{"q": "About how many countries have Spanish as an official language?", "options": ["Exactly two", "About fifty", "About twenty", "About five"]}, {"q": "Which city did Spain found in Florida in 1565?", "options": ["St. Augustine", "Orlando", "Tampa", "Miami"]}, {"q": "Puerto Rico is:", "options": ["In Asia", "In Europe", "Part of the United States", "A country in Africa"]}, {"q": "Vosotros is used mostly in:", "options": ["Florida", "Spain", "Mexico", "Cuba"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: The Spanish Speaking World and Hispanic Florida$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,1}'::int[], array[$j$Spanish is official in about twenty countries.$j$,$j$St. Augustine was founded in 1565.$j$,$j$Puerto Rico is a U.S. territory.$j$,$j$Spain uses vosotros for you all with friends.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: The Spanish Speaking World and Hispanic Florida$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: Home, Health, Weather and the Spanish Speaking World$j$, $j${"questions": [{"q": "La sala is:", "options": ["The garden", "The living room", "The garage", "The kitchen"]}, {"q": "El gato está debajo de la silla means:", "options": ["The cat is the chair", "The cat is under the chair", "The cat is on the chair", "The cat is behind the chair"]}, {"q": "Me duele la cabeza means:", "options": ["My head is big", "I have a head", "I like my head", "My head hurts"]}, {"q": "Estoy enfermo means:", "options": ["I am busy", "I am hungry", "I am sick", "I am sleepy"]}, {"q": "Llueve means:", "options": ["It is raining", "It is snowing", "It is windy", "It is hot"]}, {"q": "Juego al fútbol means:", "options": ["I play soccer", "I watch soccer", "We play soccer", "He plays soccer"]}, {"q": "La primavera is:", "options": ["Spring", "Autumn", "Summer", "Winter"]}, {"q": "Hispanic Heritage Month begins on:", "options": ["January 1", "November 1", "September 15", "July 4"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Home, Health, Weather and the Spanish Speaking World$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,2,0,0,0,2}'::int[], array[$j$Sala is living room.$j$,$j$Debajo de means under.$j$,$j$Duele is singular.$j$,$j$Enfermo means sick.$j$,$j$Llueve is from llover.$j$,$j$Juego is the yo form.$j$,$j$Primavera is spring.$j$,$j$It runs from September 15 to October 15.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Home, Health, Weather and the Spanish Speaking World$j$ on conflict (item_id) do nothing;
